// SPDX-License-Identifier: GPL-3.0-or-later - the editor's Settings tab (1.9.0): every page of the board's
// Settings menu, built from the board's own description of it (MENU and ITEM, docs/tb-sysex.md), so a
// setting added to the firmware shows here without a change to this page. A change goes to the board at
// once with SET_ITEM, which has no reply: the board keeps playing and shows CHANGED BY EDITOR. Help for each
// item comes from the manual (tb-help.js, generated by scripts/gen_settings_help.py). 1.9.4: a change made on the
// board shows here within a second (the editor asks STATE once a second; refresh() reads the values again when the
// board's changed, and where each item shows, in place).
import * as tb from './tb-protocol.js';
import { HELP, PAGES } from './tb-help.js';

const READ_AGAIN_MS = 3000; // at most one automatic re-read (on coming back to the page) this often
// 2.0.3: a list clicked open keeps its value this long. A list keeps the focus after it closes, so the focus alone
// can't say it is open (2.0.3's board test: one clicked once never showed the board's changes again).
const OPEN_MS = 5000;
const isOpen = (it) => document.activeElement === it.sel && Date.now() - (it.openAt || 0) < OPEN_MS;

// Sentence case for a name the board shows in capitals, when the manual has none for it.
const plain = (s) => s.charAt(0) + s.slice(1).toLowerCase();
// 2.0.1 moved items to other pages: a board before it names the old page, so an item found on no page of the manual's
// table is looked up by its name alone (when only one page has it).
const byName = (name) => { const keys = Object.keys(HELP).filter((k) => k.endsWith(`/${name}`)); return keys.length === 1 ? HELP[keys[0]] : null; };
const help = (page, it) => HELP[`${page}/${it.name}`] || (page === 'BUTTONS' && HELP['BUTTONS/*']) ||
  (it.name === 'RESET OPTIONS' && HELP['*/RESET OPTIONS']) || byName(it.name) || null;

// root: the tab's element; link: tb-midi.js caller(); info(): IDENTIFY's answer or null.
export function settingsTab(root, link, info) {
  const st = { pages: null, page: 0, readAt: 0, busy: false };
  root.innerHTML = `
    <p class="hint">Every setting on the TB, as its Settings menu has them. A change goes to the TB at once and is saved
      there; the TB keeps playing (its screen shows <code>CHANGED BY EDITOR</code>). Changed something on the TB itself?
      It shows here within a second (TBOSS 1.9.4 or later; before, when you come back to this page, or with
      <b>Read from the TB</b>).</p>
    <p class="hint hidden" data-role="old">Connect a TB with TBOSS 1.9 or later to see and change its settings here.</p>
    <div class="row"><button data-role="read" disabled>Read from the TB</button><span class="status" data-role="status"></span></div>
    <div class="tabs" role="tablist" data-role="pages"></div>
    <div class="settings" data-role="items"></div>`;
  const el = (role) => root.querySelector(`[data-role="${role}"]`);
  const say = tb.sayer(root, () => el('status')); // 2.0.6: a change's message right under its control (Y5)
  const supported = () => !!info() && tb.settingsSupported(info().version);

  function drawPages() {
    const tabs = el('pages'); tabs.innerHTML = '';
    (st.pages || []).forEach((p, i) => {
      const b = document.createElement('button');
      b.textContent = PAGES[p.name] || plain(p.name); b.setAttribute('role', 'tab'); b.setAttribute('aria-selected', String(i === st.page));
      b.onclick = () => { st.page = i; drawPages(); drawItems(); };
      tabs.appendChild(b);
    });
  }
  function send(it, value, shown) {
    const ctl = it.row && it.row.querySelector('.control'); // 2.0.6: its message goes just under it (board test Z2)
    if (ctl) it.row.style.setProperty('--said-top', `${ctl.offsetTop + ctl.offsetHeight}px`);
    link.send(tb.setItem(it.id, value)).then(() => say(`Sent to the TB: ${shown}.`, 'good'), (e) => say(`Not sent: ${e.message}.`, 'err'));
    root.dispatchEvent(new CustomEvent('tb-sent', { bubbles: true })); // the editor asks STATE soon: what else changed
  }
  function control(page, it) {
    const K = tb.ITEM_KIND;
    if (it.kind === K.VALUE || it.kind === K.CHOOSE) {
      const sel = document.createElement('select');
      it.labels.forEach((label, v) => sel.add(new Option(label, v)));
      sel.value = String(it.value);
      sel.setAttribute('aria-label', it.name);
      it.sel = sel; it.openAt = 0;
      sel.onmousedown = sel.onkeydown = () => { it.openAt = Date.now(); };
      sel.onblur = () => { it.openAt = 0; };
      if (it.kind === K.VALUE) {
        sel.onchange = () => { it.openAt = 0; it.value = +sel.value; send(it, it.value, `${it.name} ${it.labels[it.value]}`); };
        return [sel];
      }
      const go = document.createElement('button'); // Load / Save / Clear preset (2.0.7): pick one, then do it
      go.textContent = /^SAVE/.test(it.name) ? 'Save' : /^CLEAR/.test(it.name) ? 'Clear' : 'Load';
      go.onclick = () => {
        if (go.textContent === 'Save' && !confirm(`Save the TB's current settings over preset ${it.labels[+sel.value]}?`)) return;
        if (go.textContent === 'Clear' && !confirm(`Clear preset ${it.labels[+sel.value]}, with its own colors, curves, chords and name? This can't be undone.`)) return;
        send(it, +sel.value, `${it.name} ${it.labels[+sel.value]}`);
      };
      return [sel, go];
    }
    if (it.kind === K.TOGGLE) { // Transport / Play: start or stop
      const b = document.createElement('button');
      const label = () => { b.textContent = it.value ? 'Stop' : 'Play'; };
      label(); it.label = label;
      b.onclick = () => { it.value ^= 1; label(); send(it, it.value, it.value ? 'play' : 'stop'); };
      return [b];
    }
    const now = document.createElement('span'); now.className = 'facts';
    it.label = () => { now.textContent = it.count > 1 || it.labels[0] !== 'START' ? (it.labels[it.value] || '') + ' · on the TB only' : 'on the TB only'; };
    it.label();
    return [now];
  }
  const whereText = (it) => it.whereAt + (it.shown ? '' : ' (not shown there now)');
  function drawItems() {
    const list = el('items'); list.innerHTML = '';
    for (const q of st.pages || []) for (const it of q.items) { it.row = null; it.sel = null; it.label = null; }
    const p = st.pages && st.pages[st.page];
    if (!p) return;
    const pageName = PAGES[p.name] || plain(p.name);
    for (const it of p.items) {
      const h = help(p.name, it), name = (h && h.name !== '*' ? h.name : null) || plain(it.name);
      const row = document.createElement('div'); row.className = 'setting' + (it.shown ? '' : ' unused');
      const head = document.createElement('div'); head.className = 'name';
      const title = document.createElement('b'); title.textContent = p.name === 'BUTTONS' ? plain(it.name) : name;
      head.append(title);
      if (h && h.optional) { const o = document.createElement('small'); o.textContent = ' optional'; head.append(o); }
      const where = document.createElement('small'); where.className = 'where';
      it.whereAt = `On the TB: Settings → ${pageName} → ${p.name === 'BUTTONS' ? plain(it.name) : name}`;
      where.textContent = whereText(it); it.row = row; it.where = where;
      const ctl = document.createElement('div'); ctl.className = 'control'; ctl.append(...control(p.name, it));
      const said = document.createElement('div'); said.className = 'status said pop'; ctl.append(said); // 2.0.6
      row.dataset.said = `item${it.id}`;
      row.append(head, ctl);
      if (h) {
        const about = document.createElement('div'); about.className = 'about';
        about.innerHTML = h.values + (h.default ? ` <span class="facts">Default: ${h.default}.</span>` : '');
        row.append(about);
      }
      row.append(where);
      list.appendChild(row);
    }
  }
  async function read() {
    if (!supported() || st.busy) return;
    st.busy = true; el('read').disabled = true; say('Reading the TB\'s settings…');
    try {
      st.pages = await tb.readMenu((m) => link.ok(m, 3000));
      st.page = Math.min(st.page, st.pages.length - 1); st.readAt = Date.now();
      drawPages(); drawItems(); say('');
    } catch (e) { say(`Could not read the settings: ${e.message}.`, 'err'); }
    st.busy = false; el('read').disabled = !supported();
  }
  el('read').onclick = read;
  // 2.0.7: a preset list's names again (Load, Save, Clear preset: a preset saved, cleared or named since; board test A2)
  async function relabel(it) {
    const now = tb.decodeItem(await link.ok(tb.item(it.id), 1500));
    while (now.labels.length < now.count) {
      const more = tb.decodeItem(await link.ok(tb.item(it.id, now.labels.length), 1500));
      if (!more.labels.length) break;
      now.labels.push(...more.labels);
    }
    if (JSON.stringify(now.labels) === JSON.stringify(it.labels)) return;
    it.labels = now.labels;
    if (!it.sel || isOpen(it)) return;
    const was = it.sel.value; it.sel.innerHTML = '';
    it.labels.forEach((label, v) => it.sel.add(new Option(label, v)));
    it.sel.value = was;
  }
  // An item's value or where it shows changed on the board: its row as it is now (a list being chosen from stays).
  function update(it) {
    if (!it.row) return;
    it.row.classList.toggle('unused', !it.shown); it.where.textContent = whereText(it);
    if (it.sel && it.kind === tb.ITEM_KIND.VALUE && !isOpen(it)) it.sel.value = String(it.value);
    if (it.label) it.label();
  }
  return {
    // After connecting (or reconnecting): read everything, or say why not.
    async connected() {
      el('old').classList.toggle('hidden', supported() || !info());
      el('read').disabled = !supported();
      st.pages = null; drawPages(); drawItems();
      if (supported()) await read();
    },
    // The tab shown again, or the window back in front: read again unless just read (1.9.4 and later: STATE does).
    shown() { if (supported() && !tb.stateSupported(info().version) && Date.now() - st.readAt > READ_AGAIN_MS) read(); },
    // STATE (1.9.4): where each item shows; values (VALUES) again if the menu check changed. Returns how many changed,
    // -1 when it couldn't look (the menu not read yet, or being read): the editor asks again next time (2.0.3).
    async refresh(state, valuesChanged) {
      if (!supported() || st.busy || !st.pages) return -1;
      let values = null;
      if (valuesChanged) values = tb.decodeValues(await link.ok(tb.values(tb.KIND.LIVE, 0), 1500)).values;
      if (valuesChanged) for (const p of st.pages) for (const it of p.items) if (it.kind === tb.ITEM_KIND.CHOOSE) await relabel(it);
      let changed = 0;
      for (const p of st.pages) for (const it of p.items) {
        const v = values ? values[it.id] : undefined, shown = state.shown[it.id];
        let differs = false;
        if (v !== undefined && it.kind !== tb.ITEM_KIND.CHOOSE && v !== it.value) { it.value = v; differs = true; }
        if (shown !== undefined && shown !== it.shown) { it.shown = shown; differs = true; }
        if (differs) { changed++; update(it); }
        else if (it.sel && it.kind === tb.ITEM_KIND.VALUE && it.sel.value !== String(it.value)) update(it); // left open before
      }
      return changed;
    },
    // For the other tabs (Feel): an item by its page and name as the board shows them ({ id, labels, value, ... }),
    // null before the menu is read; read() reads it again (after changes from elsewhere).
    // page: a name, or names to try in turn (2.0.1's page first, then the one before it).
    item(page, name) {
      for (const one of [].concat(page)) {
        const p = st.pages && st.pages.find((x) => x.name === one), it = p && p.items.find((x) => x.name === name);
        if (it) return it;
      }
      return null;
    },
    // For the Presets tab's compare (1.9.3): every page with its items, as read (null before).
    pages() { return st.pages; },
    read,
  };
}
